    #[test]
    fn entry_rejects_missing_producer_binary_file() -> Result<(), String> {
        // The existence check runs before the corpus read, so a bad
        // `--producer-bin` fails cleanly without touching fixtures. The
        // command pins the process cwd to the workspace root before that
        // check, so hold the cwd write guard and restore the original
        // directory around the call — parallel tests must never observe the
        // mutation.
        let _cwd_guard = crate::acquire_test_cwd_write_guard();
        let original = std::env::current_dir().map_err(|err| err.to_string())?;
        let missing = format!(
            "target/ripr/reports/perl-migration-candidates/missing-producer-{}.bin",
            std::process::id()
        );
        let attempt = perl_migration_refresh(&["--producer-bin".to_string(), missing]);
        let restored = std::env::set_current_dir(original).map_err(|err| err.to_string());
        let Err(err) = attempt else {
            return Err("nonexistent producer binary should fail".to_string());
        };
        restored?;
        if !err.contains("does not exist as a file") || !err.contains(USAGE) {
            return Err(format!("missing-binary error should carry usage: {err}"));
        }
        Ok(())
    }

