    #[test]
    fn remove_stale_candidate_deletes_previous_refresh_output() -> Result<(), String> {
        let root =
            std::env::temp_dir().join(format!("ripr-perl-migration-stale-{}", std::process::id()));
        std::fs::create_dir_all(&root).map_err(|err| err.to_string())?;
        let candidate = root.join("ordinary_discount.json");
        std::fs::write(&candidate, b"previous run bytes").map_err(|err| err.to_string())?;
        let candidate_text = candidate
            .to_str()
            .ok_or_else(|| "candidate path is not UTF-8".to_string())?;
        remove_stale_candidate(candidate_text)?;
        if candidate.exists() {
            let _ = std::fs::remove_dir_all(&root);
            return Err("stale candidate was not removed".to_string());
        }
        // A missing file is not an error; a failing removal is.
        remove_stale_candidate(candidate_text)?;
        let _ = std::fs::remove_dir_all(&root);
        Ok(())
    }

    #[test]
    fn producer_invocation_replaces_program_and_out_placeholder() -> Result<(), String> {
        let argv = build_producer_invocation(
            "bin/perl-ripr-facts.exe",
            &sample_case(),
            "target/ripr/reports/perl-migration-candidates/ordinary_discount.json",
        )?;
        if argv[0] != "bin/perl-ripr-facts.exe" {
            return Err(format!(
                "leading token should be the supplied binary: {argv:?}"
            ));
        }
        let out_index = argv
            .iter()
            .position(|token| token == "--out")
            .ok_or_else(|| format!("argv should keep --out: {argv:?}"))?;
        let out_value = argv
            .get(out_index + 1)
            .ok_or_else(|| format!("--out should keep a value: {argv:?}"))?;
        if out_value != "target/ripr/reports/perl-migration-candidates/ordinary_discount.json" {
            return Err(format!("--out placeholder should be replaced: {argv:?}"));
        }
        if argv.iter().any(|token| token == OUT_PLACEHOLDER) {
            return Err(format!("no placeholder token should remain: {argv:?}"));
        }
        Ok(())
    }

    #[test]
    fn producer_invocation_rejects_wrong_program_and_bad_placeholder() -> Result<(), String> {
        let mut wrong_program = sample_case();
        wrong_program.producer_command = "other-producer ripr-facts --out <out>".to_string();
        let Err(program_err) = build_producer_invocation("bin", &wrong_program, "target/out.json")
        else {
            return Err("wrong leading program should fail".to_string());
        };
        if !program_err.contains("perl-ripr-facts") {
            return Err(format!(
                "program error should name the pinned binary: {program_err}"
            ));
        }

        let mut bad_placeholder = sample_case();
        bad_placeholder.producer_command = "perl-ripr-facts ripr-facts --out real.json".to_string();
        let Err(placeholder_err) =
            build_producer_invocation("bin", &bad_placeholder, "target/out.json")
        else {
            return Err("non-placeholder --out value should fail".to_string());
        };
        if !placeholder_err.contains(OUT_PLACEHOLDER) {
            return Err(format!(
                "placeholder error should name the placeholder: {placeholder_err}"
            ));
        }

        let mut no_out = sample_case();
        no_out.producer_command = "perl-ripr-facts ripr-facts".to_string();
        let Err(out_err) = build_producer_invocation("bin", &no_out, "target/out.json") else {
            return Err("missing --out should fail".to_string());
        };
        if !out_err.contains("--out") {
            return Err(format!("missing-out error should name --out: {out_err}"));
        }
        Ok(())
    }

