    #[test]
    fn extract_observed_shapes_packet_properties() -> Result<(), String> {
        let observed = extract_observed(&sample_packet());
        let get = |property: &str| {
            observed
                .get(property)
                .ok_or_else(|| format!("observed should carry `{property}`"))
        };

        if get("schema_version")? != "ripr-perl-facts-v1" {
            return Err(format!("schema_version should pass through: {observed}"));
        }
        if !get("input.diff_id")?.is_null() {
            return Err("input.diff_id null should stay null".to_string());
        }
        if get("files[].digest")? != &json!(["sha256:aaa", "sha256:bbb"]) {
            return Err(format!("file digests should be projected: {observed}"));
        }
        if get("owners[]")?
            != &json!([
                {"owner_id": "owner:pkg", "range_start_line": 0},
                {"owner_id": "owner:sub", "range_start_line": 5}
            ])
        {
            return Err(format!(
                "owners should project id plus start line: {observed}"
            ));
        }
        if get("changes[]")?
            != &json!([{
                "change_id": "change:1",
                "changed_text_digest": "fnv64:abcd",
                "missing_discriminator": null,
                "provenance_refs_len": 0
            }])
        {
            return Err(format!(
                "changes should project the shaped record: {observed}"
            ));
        }
        if get("tests[].framework")? != &json!(["Test::More"]) {
            return Err(format!("test frameworks should be projected: {observed}"));
        }
        if get("oracles[]")?
            != &json!([
                {
                    "oracle_id": "oracle:1",
                    "kind": "exact_return_assertion",
                    "strength": "strong_exact",
                    "target_owner_id": "owner:sub",
                    "has_observed_sink": true,
                    "has_expected_expression": false
                },
                {
                    "oracle_id": "oracle:2",
                    "kind": "exact_return_assertion",
                    "strength": "strong_exact",
                    "target_owner_id": null,
                    "has_observed_sink": false,
                    "has_expected_expression": false
                }
            ])
        {
            return Err(format!(
                "oracles should project presence booleans: {observed}"
            ));
        }
        if get("relations[]")?
            != &json!([{
                "relation_id": "relation:1",
                "change_id": "change:1",
                "owner_id": "owner:sub",
                "test_id": "test:1",
                "oracle_id": "oracle:1",
                "relation_kind": "direct_owner_call",
                "reachability_hint": "reachable",
                "provenance_refs_len": 1
            }])
        {
            return Err(format!(
                "relations should project shaped records: {observed}"
            ));
        }
        if get("limitations[].kind")? != &json!(["partial_emitter", "range_precision"]) {
            return Err(format!("limitation kinds should be projected: {observed}"));
        }

        let provenance = get("provenance[]")?;
        let shapes: Vec<&str> = provenance
            .as_array()
            .ok_or_else(|| format!("provenance should be an array: {provenance}"))?
            .iter()
            .filter_map(|item| item.get("range_shape").and_then(Value::as_str))
            .collect();
        if shapes != ["missing", "string", "null", "object"] {
            return Err(format!(
                "range shapes should map string/object/null/absent in order: {shapes:?}"
            ));
        }
        Ok(())
    }

