    #[test]
    fn compute_drift_reports_exactly_the_differing_property() -> Result<(), String> {
        let pinned = json!({"schema_version": "ripr-perl-facts-v1", "packet_status": "partial"});
        let candidate = json!({"schema_version": "ripr-perl-facts-v2", "packet_status": "partial"});
        let drift = compute_drift(&pinned, &candidate);
        let expected = json!([{
            "property": "schema_version",
            "pinned": "ripr-perl-facts-v1",
            "candidate": "ripr-perl-facts-v2"
        }]);
        let expected_entries = expected.as_array().cloned().unwrap_or_default();
        if drift != expected_entries {
            return Err(format!(
                "drift should match the single differing property: {drift:?}"
            ));
        }
        let identical = compute_drift(&pinned, &pinned);
        if !identical.is_empty() {
            return Err(format!(
                "identical observations should produce no drift: {identical:?}"
            ));
        }
        Ok(())
    }

    #[test]
    fn build_report_flags_byte_identity_and_property_drift() -> Result<(), String> {
        let case = sample_case();
        let candidate_path = "target/ripr/reports/perl-migration-candidates/ordinary_discount.json";
        let pinned_bytes = serde_json::to_vec(&sample_packet())
            .map_err(|err| format!("sample serialize: {err}"))?;

        let identical = build_report(
            &case,
            "bin/perl-ripr-facts.exe",
            candidate_path,
            &pinned_bytes,
            &pinned_bytes,
        )?;
        if !identical.byte_identical || identical.drift_count != 0 {
            return Err("identical bytes should mean no drift".to_string());
        }
        let value = &identical.value;
        if value.get("kind").and_then(Value::as_str) != Some(REFRESH_KIND) {
            return Err(format!("report kind should be pinned: {value}"));
        }
        if value.get("schema_version").and_then(Value::as_str) != Some(REFRESH_SCHEMA_VERSION) {
            return Err(format!("report schema_version should be pinned: {value}"));
        }
        if value.get("producer_commit_pinned").and_then(Value::as_str)
            != Some(case.producer_commit.as_str())
        {
            return Err(format!("report should pin the producer commit: {value}"));
        }
        if value.get("promotion").and_then(Value::as_str) != Some(PROMOTION_NOTE) {
            return Err(format!(
                "report should carry the manual promotion note: {value}"
            ));
        }
        let candidate_sha = value
            .get("candidate")
            .and_then(|candidate| candidate.get("packet_sha256"))
            .and_then(Value::as_str)
            .ok_or_else(|| format!("candidate should carry packet_sha256: {value}"))?;
        if candidate_sha != sha256_hex(&pinned_bytes) {
            return Err(format!(
                "candidate sha should be computed from the candidate bytes: {candidate_sha}"
            ));
        }
        let pinned_sha = value
            .get("pinned")
            .and_then(|pinned| pinned.get("packet_sha256"))
            .and_then(Value::as_str)
            .ok_or_else(|| format!("pinned should carry packet_sha256: {value}"))?;
        if pinned_sha != case.packet_sha256 {
            return Err(format!(
                "pinned sha should come from the corpus: {pinned_sha}"
            ));
        }

        let mut drifted_packet = sample_packet();
        drifted_packet["packet_status"] = json!("complete");
        let candidate_bytes = serde_json::to_vec(&drifted_packet)
            .map_err(|err| format!("drifted serialize: {err}"))?;
        let drifted = build_report(
            &case,
            "bin/perl-ripr-facts.exe",
            candidate_path,
            &pinned_bytes,
            &candidate_bytes,
        )?;
        if drifted.byte_identical || drifted.drift_count != 1 {
            return Err("a changed packet_status should be exactly one drift".to_string());
        }
        let entries = drifted
            .value
            .get("drift")
            .and_then(Value::as_array)
            .ok_or_else(|| format!("drift should be an array: {}", drifted.value))?;
        let entry = entries
            .first()
            .ok_or_else(|| format!("drift should have one entry: {}", drifted.value))?;
        if entry.get("property").and_then(Value::as_str) != Some("packet_status")
            || entry.get("pinned").and_then(Value::as_str) != Some("partial")
            || entry.get("candidate").and_then(Value::as_str) != Some("complete")
        {
            return Err(format!(
                "drift entry should name pinned and candidate: {entry}"
            ));
        }
        Ok(())
    }

    #[test]
    fn parse_corpus_parses_minimal_cases() -> Result<(), String> {
        let corpus = r#"{
            "kind": "perl_packet_contract_migration_corpus",
            "schema_version": "0.1",
            "cases": [
                {
                    "id": "ordinary_discount",
                    "producer": {
                        "repository": "EffortlessMetrics/perl-lsp-swarm",
                        "commit": "a9664af790888333efbe50a042fa060f3cc2d171",
                        "version": "0.17.0",
                        "binary": "perl-ripr-facts"
                    },
                    "producer_command": "perl-ripr-facts ripr-facts --out <out>",
                    "packet": "fixtures/perl_packet_contract_migration/producer-packets/v1/ordinary_discount.json",
                    "packet_sha256": "sha256:0cc8f4bb"
                }
            ]
        }"#;
        let cases = parse_corpus(corpus)?;
        let case = cases
            .first()
            .ok_or_else(|| "corpus should parse one case".to_string())?;
        if case.id != "ordinary_discount"
            || case.producer_binary_name != "perl-ripr-facts"
            || case.packet_sha256 != "sha256:0cc8f4bb"
        {
            return Err(format!("case should parse its identity fields: {case:?}"));
        }

        let Err(missing) = parse_corpus(r#"{"cases": [{"id": "x"}]}"#) else {
            return Err("a case without producer fields should fail".to_string());
        };
        if !missing.contains("`producer`") {
            return Err(format!("missing-producer error should be named: {missing}"));
        }

        let Err(no_cases) = parse_corpus(r#"{"kind": "other"}"#) else {
            return Err("a corpus without cases should fail".to_string());
        };
        if !no_cases.contains("cases") {
            return Err(format!(
                "missing-cases error should name `cases`: {no_cases}"
            ));
        }
        Ok(())
    }
